package com.axiom.analysis.logs; import com.axiom.analysis.fingerprint.Sha256FailureFingerprinter; import com.axiom.domain.failure.*; import com.axiom.domain.log.LogEvent; import java.util.*; import java.util.regex.*; import org.springframework.stereotype.Component;
@Component public class FailureEventExtractor {
 private static final Pattern CONDENSED_CAUSE=Pattern.compile("(?m)^\\s*Caused by: ([A-Za-z_$][\\w.$]*(?:Exception|Error)) at [\\w.$]+\\.java:\\d+\\s*$");
 private final Sha256FailureFingerprinter fingerprinter; public FailureEventExtractor(Sha256FailureFingerprinter f){fingerprinter=f;}
 public List<FailureEvent> extract(List<LogEvent> events){Map<String,FailureEvent> found=new LinkedHashMap<>();for(LogEvent event:events){String raw=event.message(),n=event.normalizedMessage();String condensed=condensedRoot(raw);FailureEventType type=condensed==null?type(raw):FailureEventType.EXCEPTION;if(type==FailureEventType.UNKNOWN)continue;String ex=condensed==null?exception(raw):condensed;String root=raw.lines().filter(x->x.trim().startsWith("at ")).findFirst().orElse("").replaceAll(":\\d+\\)",")");
 // Keep raw cause context, but exclude wrapper test identities and volatile source coordinates from the condensed root fingerprint.
 if(condensed!=null){n=condensed;root="";}
 String fp=fingerprinter.fingerprint(type,ex,n,root);FailureEvent old=found.get(fp);found.put(fp,new FailureEvent(type,ex,raw,n,raw.contains("\n")?raw:null,root,fp,old==null?1:old.occurrences()+1,old==null?event.lineStart():old.firstLine(),event.lineEnd()));}return List.copyOf(found.values());}
 private String condensedRoot(String message){Matcher matcher=CONDENSED_CAUSE.matcher(message);String root=null;while(matcher.find())root=matcher.group(1);return root;}
 private FailureEventType type(String x){String s=x.toLowerCase();if(s.contains("assertionerror")||s.contains("assertion failed"))return FailureEventType.ASSERTION;if(s.contains("connection refused")||s.contains("connection reset"))return FailureEventType.CONNECTION_ERROR;if(s.contains("timed out")||s.contains("timeout"))return FailureEventType.TIMEOUT;if(s.contains("outofmemory")||s.contains("no space left"))return FailureEventType.RESOURCE_ERROR;if(s.contains("could not resolve")||s.contains("artifact not found"))return FailureEventType.DEPENDENCY_ERROR;if(s.contains("compilation failure")||s.contains("build failed"))return FailureEventType.BUILD_ERROR;if(s.contains("exited with non-zero")||s.contains("command failed"))return FailureEventType.COMMAND_FAILURE;if(Pattern.compile("[A-Za-z_$][\\w.$]*(Exception|Error):").matcher(x).find())return FailureEventType.EXCEPTION;return s.contains("##[error]")||s.startsWith("error:")?FailureEventType.GENERIC_ERROR:FailureEventType.UNKNOWN;}
 private String exception(String x){Matcher m=Pattern.compile("([A-Za-z_$][\\w.$]*(?:Exception|Error))").matcher(x);return m.find()?m.group(1):null;}
}
